using Decont;using Xunit;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using Microsoft.AspNetCore.Identity;using System.Net;using System.Net.Http.Json;using System.Security.Claims;using System.Text.Json;using ClosedXML.Excel;
namespace Decont.Tests;
public class Pdf04PostingTests {
 static Guid RateId(int rate)=>Guid.Parse("00000000-0000-0000-0000-"+(1000+rate).ToString("D12"));
 static Master Master(string kind,string code,object data)=>new(){Kind=kind,Code=code,From=new(2020,1,1),Json=Serialization.Write(data)};
 static List<Master> Masters()=>[Master("accounting","GENERAL",new{mainAccount="TEST-GL",localAccount="TEST-LOCAL",subAccount="SUB",vehicle=false}),Master("accounting","CAR",new{mainAccount="TEST-GL",localAccount="TEST-LOCAL",subAccount="SUB",vehicle=true}),Master("expenseTypes","GENERAL",new{}),Master("expenseTypes","CAR",new{}),Master("costCenters","CC",new{erpCode="TEST-CC"}),Master("suppliers","18546294",new{vendorAccount="TEST-VENDOR"}),Master("erpSettings","default",new{approvalReference="SYNTHETIC-NOT-REAL-ERP-APPROVAL",clearingAccount="TEST-CLEAR",clearingLocal="TEST-CLEAR-LOCAL",vatAccount="TEST-VAT",vatLocal="TEST-VAT-LOCAL",otherCarNonDedAccount="TEST-NONDED",repairNonDedAccount="TEST-REPAIR",repairNonDedLocal="TEST-REPAIR-LOCAL"}),..new[]{0,5,11,19,21}.Select(rate=>new Master{Id=RateId(rate),Kind="vat",Code=rate.ToString(),From=new(2020,1,1),Json=Serialization.Write(new{rate,salesTaxGroup="VDOM",itemTaxGroup="G"+rate,deductible50Code="D"+rate,nonDeductible50Code="N"+rate})})];
 static ExpenseData Data()=>new("Supplier","18546294","PDF04-1","2026-01-01","RO","Receipt","GENERAL","Verified receipt","Personal",null,"CC",null,121,"RON",[new(RateId(21),100,21)],true,true,"RON");
 static Report Report(ExpenseData? data=null)=>new(){Purpose="PDF04",ManagerId="manager",Lines=[new(){Position=1,Json=Serialization.Write(data??Data()),EstimatedRon=(data??Data()).Amount}]};
 static ClaimsPrincipal Finance()=>new(new ClaimsIdentity([new(ClaimTypes.NameIdentifier,"finance"),new(ClaimTypes.Role,"Finance")],"test"));
 public static IEnumerable<object[]> GoldenCases()=>Enumerable.Range(1,14).Select(i=>new object[]{"ERP-"+i.ToString("D3")});
 [Theory][MemberData(nameof(GoldenCases))]public void IndependentGoldenFilesMatchEveryExportCell(string id){var fixture=JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"Fixtures","posting04",id+".json"))).RootElement;var report=new Report{Id=Guid.Parse("10000000-0000-0000-0000-000000000001"),Purpose=id,ManagerId="manager"};foreach(var item in fixture.GetProperty("inputs").EnumerateArray()){var d=Serialization.Read<ExpenseData>(item.GetProperty("data").GetRawText());report.Lines.Add(new(){Id=item.GetProperty("id").GetGuid(),ReportId=report.Id,Position=item.GetProperty("position").GetInt32(),EstimatedRon=d.Amount,Json=Serialization.Write(d)});}var masters=Masters();var engine=new Posting();if(fixture.GetProperty("expectedError").ValueKind!=JsonValueKind.Null){Assert.Equal("vat_rate",Assert.Throws<DomainException>(()=>engine.Build(report,new(){Worker="TEST-EMPLOYEE"},masters)).Code);return;}var result=engine.Build(report,new(){Worker="TEST-EMPLOYEE"},masters);var expected=Serialization.Read<List<string[]>>(fixture.GetProperty("expectedAtoX").GetRawText());Assert.Equal(fixture.GetProperty("expectedHeaders").EnumerateArray().Select(x=>x.GetString()),Posting.Headers);Assert.Equal(Serialization.Write(expected),Serialization.Write(result.Rows));var expectedLines=fixture.GetProperty("expectedPostingLines").EnumerateArray().ToList();Assert.Equal(expectedLines.Count,result.Lines.Count);for(int i=0;i<result.Lines.Count;i++){var line=result.Lines[i];Assert.Equal(expectedLines[i].GetProperty("expenseId").GetGuid(),line.ExpenseId);Assert.Equal(expectedLines[i].GetProperty("position").GetInt32(),line.Position);Assert.Equal(expectedLines[i].GetProperty("account").GetString(),line.Cells[2]);Assert.Equal(InvoiceArithmetic.Parse(expectedLines[i].GetProperty("debit").GetString()),line.Debit);Assert.Equal(InvoiceArithmetic.Parse(expectedLines[i].GetProperty("credit").GetString()),line.Credit);}Assert.All(result.Reconciliation,x=>Assert.Equal(0,x.DifferenceRon));Assert.Equal(result.Fingerprint,engine.Build(report,new(){Worker="TEST-EMPLOYEE"},masters).Fingerprint);using var workbook=new XLWorkbook(new MemoryStream(Documents.Workbook(result.Rows)));var sheet=workbook.Worksheet("Import");for(int r=0;r<expected.Count;r++)for(int col=0;col<24;col++){var cell=sheet.Cell(r+2,col+1);Assert.False(cell.HasFormula);if((col is 13 or 14)&&expected[r][col]!="")Assert.Equal(decimal.Parse(expected[r][col],System.Globalization.CultureInfo.InvariantCulture),cell.GetValue<decimal>());else Assert.Equal(expected[r][col],cell.GetString());}Assert.Null(fixture.GetProperty("accountingApprovalDate").GetString());}
 [Theory][InlineData("Personal")][InlineData("CompanyCard")]public void VehiclePercentageDefaultsTo50RegardlessOfPayment(string payment){var d=Data() with{Category="CAR",Payment=payment,CardId=payment=="CompanyCard"?Guid.NewGuid():null};var result=new Posting().Build(Report(d),new(){Worker="expense-person"},Masters());Assert.All(result.Lines,l=>{Assert.Equal(50,l.VehiclePercentage);Assert.Equal("expense-person",l.Cells[11]);});Assert.Equal("50.00",result.Rows[0][13]);Assert.Equal("50.00",result.Rows[1][13]);}
 [Theory][InlineData(0)][InlineData(25)][InlineData(75)][InlineData(100)]public void EditablePercentageConservesOriginalBaseAndVat(decimal percent){var masters=Masters();masters.Add(Master("policies",VehicleDeductibility.Code,new{percentage=percent,deductible21Code="CUSTOM-DED",nonDeductible21Code="CUSTOM-NONDED"}));var result=new Posting().Build(Report(Data() with{Category="CAR"}),new(){Worker="employee"},masters);Assert.Equal(100,result.Lines.Take(2).Sum(l=>l.Debit));Assert.Equal(21*(100-percent)/100,result.Lines.Where(l=>l.Cells[2]=="TEST-NONDED").Sum(l=>l.Debit));Assert.Equal("121.00",result.Rows[^1][14]);Assert.All(result.Reconciliation,x=>Assert.Equal(0,x.DifferenceRon));}
 [Fact]public void OtherPercentNeverSilentlyUses50PercentTaxCodes(){var masters=Masters();masters.Add(Master("policies",VehicleDeductibility.Code,new{percentage=75}));Assert.Equal("vehicle_tax_code",Assert.Throws<DomainException>(()=>new Posting().Build(Report(Data() with{Category="CAR"}),new(){Worker="employee"},masters)).Code);}
 [Fact]public void PrintedBasesAndPaidVatAreCheckedWithoutReplacement(){var d=Data() with{Amount=121.01m,Taxes=[new(RateId(21),100.01m,21)]};var r=Report(d);var preview=FinancialCalculations.Preview(r.Lines[0],Masters(),new(),"fixture");Assert.DoesNotContain(preview.Issues,p=>p.Blocking);Assert.Equal(100.01m,preview.PostingData.Taxes[0].Base);Assert.Equal(21,preview.PostingData.Taxes[0].Vat);var result=new Posting().Build(r,new(){Worker="employee"},Masters());Assert.Equal("100.01",result.Rows[0][13]);Assert.Equal("121.01",result.Rows[^1][14]);}
 [Fact]public void DefaultVehicleOddCentSplitMatchesWorkbookRounding(){var d=Data() with{Category="CAR",Amount=121.01m,Taxes=[new(RateId(21),100,21.01m)]};var result=new Posting().Build(Report(d),new(){Worker="employee"},Masters());Assert.Equal("5.25",result.Rows[3][13]);Assert.Equal("5.26",result.Rows[4][13]);Assert.Equal("10.51",result.Rows[5][14]);}
 [Fact]public void SourceMismatchIsRejectedRatherThanRebalanced(){var r=Report();r.Lines[0].EstimatedRon=122;r.Lines[0].Json=Serialization.Write(Data() with{Amount=122});Assert.Equal("posting_source_total",Assert.Throws<DomainException>(()=>new Posting().Build(r,new(){Worker="employee"},Masters())).Code);}
 [Fact]public void FiftyReceiptCapAndUnlimitedSerializerRowsAreSeparate(){var r=Report(Data() with{Country="DE",HasCompanyCui=false,Taxes=[],Amount=100});for(int i=2;i<=51;i++)r.Lines.Add(new(){Position=i,EstimatedRon=100,Json=r.Lines[0].Json});Assert.Equal("receipt_limit",Assert.Throws<DomainException>(()=>new Posting().Build(r,new(){Worker="employee"},Masters())).Code);var row=new string[24];Array.Fill(row,"");row[1]="Ledger";row[2]="TEST";row[13]="1.00";using var workbook=new XLWorkbook(new MemoryStream(Documents.Workbook(Enumerable.Range(1,1100).Select(_=>row.ToArray()).ToList())));Assert.Equal(1101,workbook.Worksheet("Import").LastRowUsed()!.RowNumber());}
 [Fact]public void SignedCarAmountsUseSameRowsAndNeverNegativeDebitCredit(){var d=Data() with{Category="CAR",Amount=-121,Taxes=[new(RateId(21),-100,-21)]};var result=new Posting().Build(Report(d),new(){Worker="employee"},Masters());Assert.All(result.Lines,l=>{Assert.True(l.Debit>=0&&l.Credit>=0);Assert.False(l.Debit>0&&l.Credit>0);});Assert.Equal("121.00",result.Rows[^1][13]);}
 [Fact]public async Task OnlyFinanceCanChangePercentageAndVersionsAreDated(){await using var f=new Factory();await f.Seed();foreach(var name in new[]{"alice","admin"}){var c=await Login(f,name);await Send(c,"/api/finance/vehicle-deductibility",new VehiclePolicyInput(75,new(2026,1,1),"Change vehicle percentage"),HttpStatusCode.Forbidden);}var finance=await Login(f,"finance");await Send(finance,"/api/finance/vehicle-deductibility",new VehiclePolicyInput(75,new(2026,1,1),"First version"));await Send(finance,"/api/finance/vehicle-deductibility",new VehiclePolicyInput(60,new(2026,1,1),"Correct percentage"));await Send(finance,"/api/finance/vehicle-deductibility",new VehiclePolicyInput(25,new(2027,1,1),"Future version"));await Send(finance,"/api/finance/vehicle-deductibility",new VehiclePolicyInput(101,new(2026,1,1),"Invalid percentage"),HttpStatusCode.UnprocessableEntity);using var scope=f.Services.CreateScope();var masters=await scope.ServiceProvider.GetRequiredService<Db>().Masters.ToListAsync();Assert.Equal(50,VehicleDeductibility.Percent(masters,new(2025,1,1)));Assert.Equal(60,VehicleDeductibility.Percent(masters,new(2026,1,1)));Assert.Equal(25,VehicleDeductibility.Percent(masters,new(2027,1,1)));}
 [Fact]public async Task ExportRetryStoresOneBatchAndExactImmutableLineSnapshots(){await using var f=new Factory();await f.Seed();var(id,version)=await Ready(f);var finance=await Login(f,"finance");var first=await Send(finance,$"/api/finance/reports/{id}/export",new VersionRequest(version,null));var batch=first.GetProperty("batchId").GetGuid();var retry=await Send(finance,$"/api/finance/reports/{id}/export",new VersionRequest(version,null));Assert.Equal(batch,retry.GetProperty("batchId").GetGuid());var bytes=await finance.GetByteArrayAsync($"/api/batches/{batch}/xlsx");using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();Assert.Single(await db.Batches.ToListAsync());var stored=await db.PostingLines.OrderBy(l=>l.Sequence).ToListAsync();Assert.Equal(3,stored.Count);Assert.NotNull(stored[0].SourceVatComponentId);Assert.All(stored,l=>Assert.NotNull(l.CalculationId));using var workbook=new XLWorkbook(new MemoryStream(bytes));var rows=Serialization.Read<List<string[]>>((await db.Batches.SingleAsync()).Rows);Assert.Equal(100,workbook.Worksheet("Import").Cell(2,14).GetValue<decimal>());Assert.Equal(Serialization.Write(rows[0]),Serialization.Write(Serialization.Read<PostingTrace>(stored[0].Json).Cells));stored[0].Account="TAMPER";await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync());}
 [Fact]public async Task AuditorCanSeeOriginalButCannotDownloadAnyAccountingExcel(){await using var f=new Factory();await f.Seed();var(id,version)=await Ready(f);using(var scope=f.Services.CreateScope()){var um=scope.ServiceProvider.GetRequiredService<UserManager<User>>();var auditor=new User{UserName="auditor",Name="Auditor",Email="auditor@example.invalid",ChangePassword=false};Assert.True((await um.CreateAsync(auditor,"Valid-test-Password1!")).Succeeded);await um.AddToRoleAsync(auditor,"Auditor");}var finance=await Login(f,"finance");var batch=(await Send(finance,$"/api/finance/reports/{id}/export",new VersionRequest(version,null))).GetProperty("batchId").GetGuid();var audit=await Login(f,"auditor");Assert.Equal(HttpStatusCode.Forbidden,(await audit.GetAsync($"/api/batches/{batch}/xlsx")).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await audit.GetAsync($"/api/reports/{id}/accounting-details")).StatusCode);Assert.Equal(HttpStatusCode.OK,(await audit.GetAsync($"/api/reports/{id}/erp-preview")).StatusCode);Guid evidence;using(var scope=f.Services.CreateScope())evidence=(await scope.ServiceProvider.GetRequiredService<Db>().Evidence.SingleAsync()).Id;Assert.Equal(HttpStatusCode.OK,(await audit.GetAsync($"/api/evidence/{evidence}")).StatusCode);Assert.Equal(HttpStatusCode.OK,(await audit.GetAsync($"/api/reports/{id}/pdf")).StatusCode);}
 [Fact]public async Task MappingChangeBlocksExportAndSavedPreviewSurvivesLaterMasterChanges(){await using var f=new Factory();await f.Seed();var(id,version)=await Ready(f);var finance=await Login(f,"finance");using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();var m=await db.Masters.SingleAsync(m=>m.Kind=="accounting"&&m.Code=="GENERAL");m.Json=m.Json.Replace("TEST-GL","TEST-NEW-GL");await db.SaveChangesAsync();}await Send(finance,$"/api/finance/reports/{id}/export",new VersionRequest(version,null),HttpStatusCode.UnprocessableEntity);var completed=await Send(finance,$"/api/reports/{id}/actions/complete",new VersionRequest(version,"Reviewed changed mapping"));var export=await Send(finance,$"/api/finance/reports/{id}/export",new VersionRequest(completed.GetProperty("version").GetInt64(),null));using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();var m=await db.Masters.SingleAsync(m=>m.Kind=="accounting"&&m.Code=="GENERAL");m.Json=m.Json.Replace("TEST-NEW-GL","TEST-LATER-GL");await db.SaveChangesAsync();}var preview=await finance.GetFromJsonAsync<JsonElement>($"/api/reports/{id}/erp-preview");Assert.True(preview.GetProperty("frozen").GetBoolean());Assert.Equal("TEST-NEW-GL",preview.GetProperty("rows")[0][2].GetString());}
 [Fact]public async Task RejectingPreviewBlocksExportWithoutRequestingManagerReapproval(){await using var f=new Factory();await f.Seed();var(id,version)=await Ready(f);var finance=await Login(f,"finance");var preview=await finance.GetFromJsonAsync<JsonElement>($"/api/reports/{id}/erp-preview");await Send(finance,$"/api/finance/reports/{id}/posting-review",new PostingReviewInput(version,"stale","ACCEPT","Review changed preview"),HttpStatusCode.Conflict);var rejected=await Send(finance,$"/api/finance/reports/{id}/posting-review",new PostingReviewInput(version,preview.GetProperty("fingerprint").GetString()!,"REJECT","Correct mapping before export"));Assert.Equal(States.Finance,rejected.GetProperty("state").GetString());Assert.Equal(1,rejected.GetProperty("revision").GetInt32());await Send(finance,$"/api/finance/reports/{id}/export",new VersionRequest(rejected.GetProperty("version").GetInt64(),null),HttpStatusCode.UnprocessableEntity);}
 [Fact]public async Task DashboardCountsExpenseOnceInsteadOfSummingGeneratedRows(){await using var f=new Factory();await f.Seed();var(id,version)=await Ready(f);var finance=await Login(f,"finance");await Send(finance,$"/api/finance/reports/{id}/export",new VersionRequest(version,null));var dashboard=await finance.GetFromJsonAsync<JsonElement>("/api/finance/posting-dashboard");Assert.Equal(1,dashboard.GetProperty("total").GetInt32());Assert.Equal(1,dashboard.GetProperty("unmatched").GetInt32());Assert.Equal(121,dashboard.GetProperty("byCategory")[0].GetProperty("total").GetDecimal());Assert.Equal(121,dashboard.GetProperty("byDepartment")[0].GetProperty("total").GetDecimal());Assert.Equal("DEPT",dashboard.GetProperty("byDepartment")[0].GetProperty("key").GetString());}
 [Fact]public async Task PostingUpgradeIsRepeatableAndSqlRejectsEvidenceMutation(){await using var f=new Factory();await f.Seed();var(id,version)=await Ready(f);var finance=await Login(f,"finance");await Send(finance,$"/api/finance/reports/{id}/export",new VersionRequest(version,null));using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();await SchemaUpgrades.Apply(db);await SchemaUpgrades.Apply(db);Assert.Single(await db.SchemaReleases.Where(r=>r.Id==9).ToListAsync());await Assert.ThrowsAnyAsync<Exception>(()=>db.Database.ExecuteSqlRawAsync("UPDATE \"PostingLines\" SET \"Reason\" = 'tampered'"));Assert.Equal(3,await db.PostingLines.CountAsync());}
