 [Fact]public async Task AdminCannotBypassFinancePercentageControlThroughMasterRoutes(){await using var f=new Factory();await f.Seed();var admin=await Login(f,"admin");await Send(admin,"/api/configuration/masters",new MasterInput("policies",VehicleDeductibility.Code,"Auto","Vehicle","{\"percentage\":75}",new(2020,1,1),null,true,"Attempted policy bypass"),HttpStatusCode.Forbidden);var finance=await Login(f,"finance");var record=await Send(finance,"/api/finance/vehicle-deductibility",new VehiclePolicyInput(50,new(2026,1,1),"Owner default"));await Send(admin,"/api/configuration/masters/"+record.GetProperty("id").GetGuid()+"/retire",new RetireInput(new(2026,12,31),"Attempted policy retirement"),HttpStatusCode.Forbidden);}
 [Fact]public async Task LegacyExportUpgradePreservesFileAndAddsPostingStorage(){await using var f=new Factory();await f.Seed();using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();var report=new Report();db.Reports.Add(report);db.Batches.Add(new(){ReportId=report.Id,FileHash="UNCHANGED-ORIGINAL-HASH",Rows="[]"});await db.SaveChangesAsync();db.ChangeTracker.Clear();await db.Database.ExecuteSqlRawAsync("DROP TABLE \"PostingLines\"");await db.Database.ExecuteSqlRawAsync("DROP TABLE \"PostingReviews\"");await db.Database.ExecuteSqlRawAsync("DROP INDEX \"IX_Batches_BusinessKey\"");foreach(var column in new[]{"ReportVersion","FinanceHash","BusinessKey","PostingFingerprint","Reconciliation","SnapshotJson"})await db.Database.ExecuteSqlRawAsync("ALTER TABLE \"Batches\" DROP COLUMN \""+column+"\"");await SchemaUpgrades.Apply(db);await SchemaUpgrades.Apply(db);var saved=await db.Batches.SingleAsync();Assert.Equal("UNCHANGED-ORIGINAL-HASH",saved.FileHash);Assert.Equal("",saved.PostingFingerprint);Assert.Empty(await db.PostingLines.ToListAsync());await Assert.ThrowsAnyAsync<Exception>(()=>db.Database.ExecuteSqlRawAsync("UPDATE \"Batches\" SET \"Rows\" = '[1]'"));db.ChangeTracker.Clear();Assert.Equal("[]",(await db.Batches.SingleAsync()).Rows);}
 static async Task<(Guid,long)> Ready(Factory f){using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();var masters=Masters();db.Masters.AddRange(masters);var employee=await db.Users.SingleAsync(u=>u.UserName=="alice");var manager=await db.Users.SingleAsync(u=>u.UserName=="manager");var r=Report();r.EmployeeId=employee.Id;r.ManagerId=manager.Id;r.DepartmentCode="DEPT";r.State=States.Finance;r.Revision=1;r.EmployeeWorker=employee.Worker;r.EmployeeName=employee.Name;var bytes=Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a16kAAAAASUVORK5CYII=");r.Lines[0].Evidence.Add(new(){Name="receipt.png",Mime="image/png",Scan="Clean",Hash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes)),Key="pdf04-test-source",Size=bytes.Length});db.Reports.Add(r);db.Decisions.Add(new(){ReportId=r.Id,Revision=1,Action="approve",Actor=manager.Id});await db.SaveChangesAsync();await scope.ServiceProvider.GetRequiredService<IStore>().Put("pdf04-test-source",bytes,"image/png");await new Reports(db).Action(r,Finance(),"complete","Synthetic Finance review");await db.SaveChangesAsync();return(r.Id,r.Version);}
 static async Task<HttpClient> Login(Factory f,string name){var c=f.CreateClient(new(){HandleCookies=true,AllowAutoRedirect=false});var token=await c.GetFromJsonAsync<JsonElement>("/api/auth/csrf");c.DefaultRequestHeaders.Add("X-CSRF-TOKEN",token.GetProperty("token").GetString());var login=await c.PostAsJsonAsync("/api/auth/login",new{username=name,password="Valid-test-Password1!"});Assert.Equal(HttpStatusCode.OK,login.StatusCode);token=await c.GetFromJsonAsync<JsonElement>("/api/auth/csrf");c.DefaultRequestHeaders.Remove("X-CSRF-TOKEN");c.DefaultRequestHeaders.Add("X-CSRF-TOKEN",token.GetProperty("token").GetString());return c;}
 static async Task<JsonElement> Send(HttpClient c,string path,object body,HttpStatusCode status=HttpStatusCode.OK){c.DefaultRequestHeaders.Remove("Idempotency-Key");c.DefaultRequestHeaders.Add("Idempotency-Key",Guid.NewGuid().ToString());var response=await c.PostAsJsonAsync(path,body);var json=await response.Content.ReadAsStringAsync();Assert.True(response.StatusCode==status,$"{response.StatusCode}: {json}");return JsonDocument.Parse(string.IsNullOrWhiteSpace(json)?"{}":json).RootElement.Clone();}
}
